344:bool ReadScope(TokenList& output_tokens, const char* input, const char*& cursor, const char* end, bool const is64bits)
345:{
346:    // the first word contains the offset at which this block ends
347:    const uint64_t end_offset = is64bits ? ReadDoubleWord(input, cursor, end) : ReadWord(input, cursor, end);
348:
349:    // we may get 0 if reading reached the end of the file -
350:    // fbx files have a mysterious extra footer which I don't know
351:    // how to extract any information from, but at least it always
352:    // starts with a 0.
353:    if(!end_offset) {
354:        return false;
355:    }
356:
357:    if(end_offset > Offset(input, end)) {
358:        TokenizeError("block offset is out of range",input, cursor);
359:    }
360:    else if(end_offset < Offset(input, cursor)) {
361:        TokenizeError("block offset is negative out of range",input, cursor);
362:    }
363:
364:    // the second data word contains the number of properties in the scope
365:    const uint64_t prop_count = is64bits ? ReadDoubleWord(input, cursor, end) : ReadWord(input, cursor, end);
366:
367:    // the third data word contains the length of the property list
368:    const uint64_t prop_length = is64bits ? ReadDoubleWord(input, cursor, end) : ReadWord(input, cursor, end);
369:
370:    // now comes the name of the scope/key
371:    const char* sbeg, *send;
372:    ReadString(sbeg, send, input, cursor, end);
373:
374:    output_tokens.push_back(new_Token(sbeg, send, TokenType_KEY, Offset(input, cursor) ));
375:
376:    // now come the individual properties
377:    const char* begin_cursor = cursor;
378:
379:    if ((begin_cursor + prop_length) > end) {
380:        TokenizeError("property length out of bounds reading length ", input, cursor);
381:    }
382:
383:    for (unsigned int i = 0; i < prop_count; ++i) {
384:        ReadData(sbeg, send, input, cursor, begin_cursor + prop_length);
385:
386:        output_tokens.push_back(new_Token(sbeg, send, TokenType_DATA, Offset(input, cursor) ));
387:
388:        if(i != prop_count-1) {
389:            output_tokens.push_back(new_Token(cursor, cursor + 1, TokenType_COMMA, Offset(input, cursor) ));
390:        }
391:    }
392:
393:    if (Offset(begin_cursor, cursor) != prop_length) {
394:        TokenizeError("property length not reached, something is wrong",input, cursor);
395:    }
396:
397:    // at the end of each nested block, there is a NUL record to indicate
398:    // that the sub-scope exists (i.e. to distinguish between P: and P : {})
399:    // this NUL record is 13 bytes long on 32 bit version and 25 bytes long on 64 bit.
400:    const size_t sentinel_block_length = is64bits ? (sizeof(uint64_t)* 3 + 1) : (sizeof(uint32_t)* 3 + 1);
401:
402:    if (Offset(input, cursor) < end_offset) {
403:        if (end_offset - Offset(input, cursor) < sentinel_block_length) {
404:            TokenizeError("insufficient padding bytes at block end",input, cursor);
405:        }
406:
407:        output_tokens.push_back(new_Token(cursor, cursor + 1, TokenType_OPEN_BRACKET, Offset(input, cursor) ));
408:
409:        // XXX this is vulnerable to stack overflowing ..
410:        while(Offset(input, cursor) < end_offset - sentinel_block_length) {
411:                    ReadScope(output_tokens, input, cursor, input + end_offset - sentinel_block_length, is64bits);
412:        }
413:        output_tokens.push_back(new_Token(cursor, cursor + 1, TokenType_CLOSE_BRACKET, Offset(input, cursor) ));
414:
415:        for (unsigned int i = 0; i < sentinel_block_length; ++i) {
416:            if(cursor[i] != '\0') {
417:                TokenizeError("failed to read nested block sentinel, expected all bytes to be 0",input, cursor);
418:            }
419:        }
420:        cursor += sentinel_block_length;
421:    }
422:
423:    if (Offset(input, cursor) != end_offset) {
424:        TokenizeError("scope length not reached, something is wrong",input, cursor);
425:    }
426:
427:    return true;
428:}
